"""Additional reviewed questions: (subject, topic, difficulty, question, options, answer, explanation).
Category is derived from the subject (Verbal / Aptitude / otherwise Technical)."""

Q = []
def add(subject, topic, diff, q, opts, ans, exp):
    assert ans in opts, (topic, q)
    Q.append((subject, topic, diff, q, opts, ans, exp))

# ---------------- Python ----------------
add("Python","Lists","Medium","What is the output of print([1, 2, 3][-1])?",["3","1","Error","[3]"],"3","Index -1 refers to the last element.")
